-- ============================================================
-- AI-drafted anatomy exam bank, one short paper per structure.
--
-- Groups follow the 3D atlas systems so a student can sit bones,
-- muscles, arteries, veins, nerves or the heart separately, and
-- every paper is about one named structure inside that group.
--
-- The text was written by the assistant through /api/exam
-- (mode: draft) and is stored with source = 'ai'. A teacher should
-- read it before it counts toward a grade; /admin can archive or
-- republish any paper at any time.
--
-- Run supabase/schema.sql first. This file is idempotent: it skips
-- any paper whose title is already in the bank, so re-running it
-- never doubles the questions.
-- ============================================================

do $$
declare e_id bigint;
begin
  if not exists (select 1 from public.exams where title = 'Яс: гуяны яс') then
    insert into public.exams (title, title_en, topic, level, time_limit_min, pass_pct, status, group_key, part_key, part_mn, source)
      values ('Яс: гуяны яс', 'Bones: femur', 'Яс', 'basic', 6, 80, 'published', 'skeletal', 'femur', 'гуяны яс', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Гуяны ясны (femur) толгой ямар бүтцийн тусламжтайгаар түүний хүзүү болон их биетэй холбогддог вэ?', 'By what structural feature does the head of the femur connect to its neck and shaft?', '["Бага эргүүлэг (Lesser trochanter)", "Үений гадаргуу (Articular surface)", "Хойд хэсгийн ялтас (Linea aspera)", "Их эргүүлэг (Greater trochanter)"]', 3, 'Гуяны ясны анатомийн бүтцийг зөв тодорхойлох.', 'femur', 2),
      (e_id, 2, 'mcq', 'Гуяны ясны (femur) араг талд байрлах, булчин бэхлэгддэг босоо чиглэлийн ясны түрхрээ буюу шугамыг хэрхэн нэрлэдэг вэ?', 'What is the vertical ridge on the posterior aspect of the femoral shaft for muscle attachment called?', '["Crista iliaca", "Pecten ossis pubis", "Linea intertrochanterica", "Linea aspera"]', 3, 'Гуяны ясны их биеийн араг талын бүтцийг таних.', 'femur', 2),
      (e_id, 3, 'mcq', 'Гуяны ясны (femur) толгойн дотор хэсэгт цусан хангамжийг дамжуулдаг гол судасны ховил аль хэсэгт байрладаг вэ?', 'Where is the pit (fovea) located on the head of the femur that transmits the blood supply to the femoral head?', '["Их эргүүлэг (Greater trochanter)", "Үений булцуу хоорондын ховил (Intercondylar fossa)", "Гуяны ясны толгойн хонхорхой (Fovea capitis femoris)", "Бага эргүүлэг (Lesser trochanter)"]', 2, 'Гуяны ясны толгойн цусан хангамжийн анатомийг мэдэх.', 'femur', 2),
      (e_id, 4, 'mcq', 'Гуяны ясны (femur) доод төгсгөлд байрлах хоёр булцууг урд хэсэгт нь юу холбож үений гадаргуу үүсгэдэг вэ?', 'What connects the two condyles of the femur anteriorly to form an articular surface for the patella?', '["Эргүүлэг хоорондын шугам (Intertrochanteric line)", "Өвдөгний хучуур гадаргуу (Patellar surface)", "Шилбэний сэртэн (Tibial tuberosity)", "Булцуу хоорондын шугам (Intercondylar line)"]', 1, 'Гуяны ясны алслагдсан төгсгөлийн анатомийг тодорхойлох.', 'femur', 2),
      (e_id, 5, 'case', '55 настай эрэгтэй хальтирч унасны улмаас баруун гуяны дээд хэсгээр маш хүчтэй өвдөж, хөлөө хөдөлгөж чадахгүй эмнэлэгт ирэв. Рентген зургаар гуяны ясны хүзүүний хугарал (femoral neck fracture) оношлогдов. Гуяны ясны толгой болон хүзүүний цусан хангамж алдагдсанаас үүсч болох хүндрэл юу вэ? Анатомийн бүтцэд үндэслэн тайлбарлана уу.', 'A 55-year-old male presents with severe right upper thigh pain and inability to move his leg after a fall. X-ray confirms a femoral neck fracture. Based on anatomy, what complication may arise due to compromised blood supply to the head and neck of the femur?', '[]', null, 'Оюутан гуяны ясны (femur) толгойн цусан хангамж (тухайлбал гуяны ясны толгойн холбоосын судас болон эргэн тойрны артериуд) тасарснаар үхжил буюу яс үхжих (avascular necrosis) эмгэг үүсэх эрсдэлтэйг бүтэн зөв тайлбарласан байх.', 'femur', 2);
  end if;
end;
$$;

do $$
declare e_id bigint;
begin
  if not exists (select 1 from public.exams where title = 'Яс: бугалганы яс') then
    insert into public.exams (title, title_en, topic, level, time_limit_min, pass_pct, status, group_key, part_key, part_mn, source)
      values ('Яс: бугалганы яс', 'Bones: humerus', 'Яс', 'basic', 6, 80, 'published', 'skeletal', 'humerus', 'бугалганы яс', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Бугалганы ясны (humerus) толгой хэсэг аль анатомийн бүтцээр дамжин ясны бусад хэсгээс тусгаарлагддаг вэ?', 'Which anatomical structure separates the head of the humerus from the rest of the bone?', '["Мэс заслын хүзүү (Surgical neck)", "Бага товгор (Lesser tubercle)", "Их товгор (Greater tubercle)", "Анатомийн хүзүү (Anatomical neck)"]', 3, 'Бугалганы ясны анатомийн болон мэс заслын хүзүүний ялгааг мэддэг байх.', 'humerus', 2),
      (e_id, 2, 'mcq', 'Бугалганы ясны дунд хэсгээр (shaft) ар талаар нь ямар мэдрэл ясны ховил дагуу явдаг вэ?', 'Which nerve runs along the radial groove on the posterior aspect of the shaft of the humerus?', '["Дунд шууны мэдрэл (Median nerve)", "Суганы мэдрэл (Axillary nerve)", "Тохойн мэдрэл (Ulnar nerve)", "Цацраг мэдрэл (Radial nerve)"]', 3, 'Бугалганы ясны бүтцийн ховил болон түүнтэй холбогдох мэдрэлийн топографийн мэдлэг.', 'humerus', 2),
      (e_id, 3, 'mcq', 'Бугалганы ясны мэс заслын хүзүүний (surgical neck) хугарлын үед хамгийн түрүүнд гэмтэх эрсдэлтэй судас-мэдрэлийн багцыг нэрлэнэ үү.', 'Which neurovascular bundle is most at risk of injury during a fracture of the surgical neck of the humerus?', '["Борвины артери ба дунд шууны мэдрэл (Brachial artery and median nerve)", "Гуяны артери ба гуяны мэдрэл (Femoral artery and femoral nerve)", "Гарын шууны артери ба цацраг мэдрэл (Radial artery and radial nerve)", "Суганы мэдрэл ба далавчин шууны артери (Axillary nerve and posterior circumflex humeral artery)"]', 3, 'Бугалганы ясны мэс заслын хүзүүний хугарал ба түүнтэй холбоотой суганы мэдрэлийн гэмтлийн хамаарлыг тодорхойлох.', 'humerus', 2),
      (e_id, 4, 'mcq', 'Бугалганы ясны босоо амны дунд хэсгийн гадна гадаргуу дээр байрладаг гурвалжин хэлбэртэй булчин бэхлэгддэг ямар бүтцийг нэрлэдэг вэ?', 'What is the name of the V-shaped rough surface located on the lateral side of the shaft of the humerus where the deltoid muscle attaches?', '["Далавчин ховил (Intertubercular sulcus)", "Цацраг мэдрэлийн ховил (Radial groove)", "Гурвалжин булчингийн хотгор (Deltoid tuberosity)", "Цээжний том булчингийн ховил (Crest of greater tubercle)"]', 2, 'Бугалганы ясны гадаргуу дээрх булчин бэхлэгдэх товгор хэсгийн байрлалыг таних.', 'humerus', 2),
      (e_id, 5, 'case', '55 настай эрэгтэй дугуйнаас унаж баруун гараараа тулж унасны улмаас бугалганы ясны босоо амны дунд хэсгээр хүчтэй өвдөж, баруун гарын шуу болон сарвуугаа тэнийлгэж чадахгүй болжээ. Эмнэлэгт үзүүлэхэд бугалганы ясны дунд хэсгийн хугарал оношлогдов. Энэ тохиолдолд ямар мэдрэл гэмтсэн байх магадлалтай вэ? Мөн уг мэдрэлийн гэмтлээс шалтгаалан ямар клиникийн шинж тэмдэг илрэх вэ?', 'A 55-year-old male fell from a bicycle onto his outstretched right arm, resulting in severe pain in the mid-shaft of his right arm and an inability to extend his right wrist and fingers. X-ray confirms a mid-shaft fracture of the humerus. Which nerve is most likely injured in this case, and what characteristic clinical sign will present?', '[]', null, 'Зөв хариулт нь Цацраг мэдрэл (Radial nerve) бөгөөд илрэх үндсэн шинж нь ''Унжгар сарвуу'' (Wrist drop) юм. Оюутан бугалганы ясны босоо амны дунд хэсгийн хугарал цацраг мэдрэлийг гэмтээдэг болохыг, мөн үүний улмаас сарвуугаа тэнийлгэх булчингууд параличдсанаас болж унжгар сарвуу үүсдэгийг бүтэн тайлбарласан байна.', 'humerus', 2);
  end if;
end;
$$;

do $$
declare e_id bigint;
begin
  if not exists (select 1 from public.exams where title = 'Яс: дал') then
    insert into public.exams (title, title_en, topic, level, time_limit_min, pass_pct, status, group_key, part_key, part_mn, source)
      values ('Яс: дал', 'Bones: scapula', 'Яс', 'basic', 6, 80, 'published', 'skeletal', 'scapula', 'дал', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Далны (scapula) ясны анатомийн бүтцэд аль нь хамаарах вэ?', 'Which of the following is an anatomical structure of the scapula?', '["Styloid process (Шөвгөр сэртэн)", "Acromion (Мөрний сэртэн)", "Medial epicondyle (Дунд талын булцуу)", "Olecranon (Тохой)"]', 1, 'Acromion нь далны ясны дээд хэсэгт орших бөгөөд эгэмний ястай нийлж үе үүсгэдэг анатомийн бүтцэд хамаарна.', 'scapula', 2),
      (e_id, 2, 'mcq', 'Далны ясны байрлалыг зөв тодорхойлсон хэсгийг олно уу.', 'Identify the correct description of the location of the scapula.', '["Цээжний хөндийн ар талд, 2 дугаар хавиргаас 7 дугаар хавирга хүртэл", "Хэвлийн арын хананд", "Цээжний хөндийн урд хананд, 1-ээс 5 дугаар хавирганы түвшинд", "Нурууны баганын дагуу ууцны хэсэгт"]', 0, 'Дал нь цээжний араг ясны арын хэсэгт, ихэвчлэн 2 дугаар хавиргаас 7 дугаар хавирганы хооронд байрладаг гурвалжин хавтгай яс юм.', 'scapula', 2),
      (e_id, 3, 'mcq', 'Далны ясны булчингийн холбоос болон хөдөлгөөнийг хангахад оролцдог гол мэдрэл аль вэ?', 'Which main nerve supplies the muscles related to the movement of the scapula?', '["Dorsal scapular nerve (Далны нурууны мэдрэл)", "Femoral nerve (Гуяны мэдрэл)", "Median nerve (Голч мэдрэл)", "Sciatic nerve (Суудайн мэдрэл)"]', 0, 'Dorsal scapular nerve нь дал өргөгч болон том, жижиг ромбо хэлбэртэй булчингуудыг мэдрүүлдэг.', 'scapula', 2),
      (e_id, 4, 'mcq', 'Далны ясны антериор (урд) гадаргуу дээр байрлах хонхойсон хэсгийг нэрлэнэ үү.', 'Name the depressed area located on the anterior (costal) surface of the scapula.', '["Subscapular fossa (Далны доорх хонхор)", "Glenoid cavity (Булчингийн үений хонхор)", "Infraspinous fossa (Далны доод хонхор)", "Supraspinous fossa (Далны дээд хонхор)"]', 0, 'Subscapular fossa нь далны ясны цээжний хөндий рүү харсан урд гадаргуу дээр байрладаг бөгөөд энд subscapularis булчин бэхлэгддэг.', 'scapula', 2),
      (e_id, 5, 'case', 'Өвчтөн мөрөндөө хүнд бэртэл авсны улмаас га гараа хажуу тийш өргөж чадахгүй, мөн далны ясны ар хэсгээр булчингийн хатингаршил үүсчээ. Энэ нь аль ясны ямар хэсгийн гэмтэл болон ямар мэдрэлийн эмгэгтэй холбоотой байж болох вэ? Товч тайлбарлана уу.', 'A patient presents with inability to abduct the arm and atrophy of the posterior scapular muscles following severe shoulder trauma. Which bone structure and nerve involvement could be associated with this condition? Explain briefly.', '[]', null, 'Хариултанд дараах зүйлсийг заавал тусгасан байна: 1. Далны ясны эргэн тойрон дахь анатомийн бүтэц (жишээ нь: scapular notch эсвэл spinoglenoid notch). 2. Suprascapular nerve (Дал дээд мэдрэлийн) гэмтэл байж болохыг тодорхойлох. 3. Supraspinatus болон infraspinatus булчингуудын үйл ажиллагаа алдагдсанаас болж мөрний хөдөлгөөн хязгаарлагдаж байгааг тайлбарласан байх.', 'scapula', 2);
  end if;
end;
$$;

do $$
declare e_id bigint;
begin
  if not exists (select 1 from public.exams where title = 'Булчин: бугалганы хоёр толгойт булчин') then
