      values ('Булчин: бугалганы хоёр толгойт булчин', 'Muscles: biceps brachii', 'Булчин', 'basic', 6, 80, 'published', 'muscular', 'biceps brachii', 'бугалганы хоёр толгойт булчин', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Бугалганы хоёр толгойт булчин (musculus biceps brachii)-гийн тохой үе нугалах болон шууг гадагш эргүүлэх (supination) үйлдлийг аль мэдрэл хангадаг вэ?', 'Which nerve supplies the innervation for flexion of the elbow and supination of the forearm by the musculus biceps brachii?', '["Musculocutaneous nerve", "Radial nerve", "Median nerve", "Ulnar nerve"]', 0, 'Зөв хариулт: Musculocutaneous nerve. Энэ мэдрэл нь бугалганы хоёр толгойт булчингийн хөдөлгөөний үүргийг хангадаг.', 'biceps brachii', 2),
      (e_id, 2, 'mcq', 'Musculus biceps brachii булчингийн үйлдэлд аль нь хамаарах вэ?', 'Which of the following actions is performed by the musculus biceps brachii?', '["Extension of the elbow and pronation of the forearm", "Flexion of the elbow and supination of the forearm", "Extension of the shoulder and extension of the elbow", "Flexion of the shoulder and pronation of the forearm"]', 1, 'Зөв хариулт: Flexion of the elbow and supination of the forearm.', 'biceps brachii', 2),
      (e_id, 3, 'mcq', 'Musculus biceps brachii булчингийн Latin нэр томьёог сонгоно уу.', 'Choose the Latin anatomical term for the biceps brachii muscle.', '["Musculus coracobrachialis", "Musculus biceps brachii", "Musculus brachialis", "Musculus triceps brachii"]', 1, 'Зөв хариулт: Musculus biceps brachii.', 'biceps brachii', 2),
      (e_id, 4, 'mcq', 'Musculus biceps brachii булчинг мэдрүүлдэг мэдрэлийг анатомийн нэршлээр нь олно уу.', 'Identify the nerve supplying the musculus biceps brachii.', '["Musculocutaneous nerve", "Axillary nerve", "Femoral nerve", "Sciatic nerve"]', 0, 'Зөв хариулт: Musculocutaneous nerve.', 'biceps brachii', 2),
      (e_id, 5, 'case', '24 настай эрэгтэй хүнд хүнд юм өргөх үед мөр болон бугалганы хэсгээр огцом өвдөлт мэдрэгдэж, тохойгоор нугалах болон шууг гадагш эргүүлэх чадвар нь суларсан байна. Үзлэгээр бугалганы хоёр толгойт булчингийн (musculus biceps brachii) үйл ажиллагаа алдагдсан нь тогтоогджээ. Энэ булчингийн үйлдэл болон түүнийг хангадаг мэдрэлийг тодорхойлж бичнэ үү.', 'A 24-year-old male presents with sudden sharp pain in the arm while lifting a heavy object, accompanied by decreased ability to flex the elbow and supinate the forearm. Examination reveals dysfunction of the musculus biceps brachii. Describe the function and the nerve supply of this muscle.', '[]', null, 'Хариултанд дараах зүйлсийг бүрэн тусгасан байна: 1. Musculus biceps brachii нь тохой үеийг нугалж, шууг гадагш эргүүлэх (supinates the forearm) үйлдэлтэйг дурдах. 2. Энэ бүтцийг musculocutaneous nerve мэдрүүлдэг болохыг зөв бичсэн байх.', 'biceps brachii', 2);
  end if;
end;
$$;

do $$
declare e_id bigint;
begin
