      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Өгзөгний их булчингийн (M. gluteus maximus) үндсэн үйлдэл аль вэ?', 'What is the primary action of the gluteus maximus muscle?', '["Чөээжийг хойшоо гэдийлгэх", "Өвдөгний үеийг тэнийлгэх", "Түнхний үеийг нугалах болон дотогш эргүүлэх", "Түнхний үеийг тэнийлгэх болон гадагш эргүүлэх"]', 3, '', 'gluteus maximus', 2),
      (e_id, 2, 'mcq', 'Өгзөгний их булчингийн мэдрэлжүүлэлтийг хангадаг мэдрэлийг нэрлэнэ үү.', 'Which nerve supplies the gluteus maximus muscle?', '["Гуяны мэдрэл", "Суудлын мэдрэл", "Дээд өгзөгний мэдрэл", "Доод өгзөгний мэдрэл"]', 3, '', 'gluteus maximus', 2),
      (e_id, 3, 'mcq', 'Өгзөгний их булчингийн латин нэршил аль вэ?', 'What is the Latin anatomical name for the gluteus maximus muscle?', '["Musculus gluteus maximus", "Musculus gluteus minimus", "Musculus piriformis", "Musculus gluteus medius"]', 0, '', 'gluteus maximus', 2),
      (e_id, 4, 'mcq', 'Өгзөгний их булчингийн үйл ажиллагаанд дараах аль нь хамаарах вэ?', 'Which of the following movements is assisted by the gluteus maximus muscle?', '["Өвдөгний үеийг түгжих", "Шагайг дотогш нугалах", "Хөлийн өлмий дээр зогсох", "Суусан байрлалаас босох"]', 3, '', 'gluteus maximus', 2),
      (e_id, 5, 'case', 'Өвчтөн шатаар өгсөх болон суусан байрлалаас босоход хүндрэлтэй байна гэсэн зовиуртай иржээ. Мэдрэлийн болон булчингийн үзлэгээр доод өгзөгний мэдрэлийн (inferior gluteal nerve) гэмтэл тогтоогдов. Аль булчингийн үйл ажиллагаа алдагдсан бэ? Булчингийн нэр, үйлдэл болон холбогдох мэдрэлийг бүтэн бичнэ үү.', 'A patient presents with difficulty climbing stairs and rising from a seated position. Examination reveals an injury to the inferior gluteal nerve. Which muscle''s function is primarily impaired? Describe the muscle name, its main action, and nerve supply.', '[]', null, 'Өвчтөнд алдагдсан булчин нь өгзөгний их булчин (M. gluteus maximus) бөгөөд энэ нь түнхний үеийг тэнийлгэх, гадагш эргүүлэх, суусан байрлалаас босоход оролцдог. Уг булчин нь доод өгзөгний мэдрэлээр (inferior gluteal nerve) мэдрэлжүүлэгддэг болохыг бүтэн зөв тайлбарласан байна.', 'gluteus maximus', 2);
  end if;
end;
$$;

