      values ('Венийн судас: дээд хөндий вен', 'Veins: superior vena cava', 'Венийн судас', 'basic', 6, 80, 'published', 'venous', 'superior vena cava', 'дээд хөндий вен', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Дээд хөндий вен (superior vena cava) нь хүний биеийн аль хэсгээс цусыг цуглуулж зүрхний аль хөндий рүү цутгадаг вэ?', 'From which parts of the human body does the superior vena cava collect blood, and into which heart chamber does it drain?', '["Толгой, хүзүү, дээд мөч болон цээжний хөндийн зарим хэсгээс цусыг цуглуулж баруун тосгуурт цутгана", "Уушигны эдээс цусыг цуглуулж зүүн тосгуурт цутгана", "Доод мөч болон хэвлийн хөндийн эрхтнүүдээс цусыг цуглуулж баруун ховдолд цутгана", "Зөвхөн толгой, хүзүүний хэсгээс цусыг цуглуулж зүрхний зүүн тосгуурт цутгана"]', 0, '', 'superior vena cava', 2),
      (e_id, 2, 'mcq', 'Дээд хөндий вен (superior vena cava) үүсэхэд аль судаснууд нийлдэг вэ?', 'Which vessels join to form the superior vena cava?', '["Баруун ба зүүн эгэмний доод венүүд", "Баруун ба зүүн толгой-багануурын венүүд (brachiocephalic veins)", "Баруун ба зүүн доод хөндий венүүд", "Баруун ба зүүн эзэн хааны венүүд (azygos veins)"]', 1, '', 'superior vena cava', 2),
      (e_id, 3, 'mcq', 'Дээд хөндий венийн (superior vena cava) анатомийн байрлал болон хөрш бүтцийг зөв тодорхойлсон хэсгийг олно уу.', 'Identify the correct anatomical position and neighboring structures of the superior vena cava.', '["Гол судасны цагираг болон зүрхний зүүн ховдлыг шууд ороон байрладаг", "Цээжний хөндийн зүүн талд байрлаж, гол судасны (aorta) зүүн хажуугаар доош явна", "Зөвхөн хэвлийн хөндийд элэгний ар талд байрладаг", "Цээжний хөндийн урд дээд хэсэгт, баруун уушигны үндэс болон өсөх гол судасны (ascending aorta) хооронд байрлана"]', 3, '', 'superior vena cava', 2),
      (e_id, 4, 'mcq', 'Дээд хөндий венийн (superior vena cava) доод хэсэгт зүрхний баруун тосгуурт орохын өмнө ямар судас цутгадаг вэ?', 'Which vein drains into the lower part of the superior vena cava just before it enters the right atrium?', '["Бөөрний вен (renal vein)", "Дэлүүний вен (splenic vein)", "Өрцний вен (phrenic vein)", "Эзэн хааны вен (azygos vein)"]', 3, '', 'superior vena cava', 2),
      (e_id, 5, 'case', '65 настай эрэгтэй амьсгаадах, нүүр болон хүзүүгээр хавдах, хүзүүний вен өргөсөх, цээжний дээд хэсгийн арьсны судсууд тэлэгдэх (superior vena cava syndrome) шинж тэмдэгтэйгээр эмнэлэгт ирэв. CT шинжилгээгээр баруун уушигны дээд дэлэнгийн хавдар дээд хөндий венийг шахаж, цусны эргэлтийг саатуулсан болох нь тогтоогдов. Дээд хөндий венийн анатомийн байрлал болон энэхүү хам шинжийн үед илрэх гол шалтгааныг тайлбарлан бичнэ үү.', 'A 65-year-old male presents with dyspnea, swelling of the face and neck, distended neck veins, and dilated chest wall veins (superior vena cava syndrome). CT scan reveals a right upper lobe lung tumor compressing the superior vena cava and impairing blood flow. Describe the anatomical location of the superior vena cava and the main pathophysiological reason for this syndrome.', '[]', null, 'Оюутан дараах санааг бүрэн тусгасан байна: 1. Дээд хөндий вен нь цээжний хөндийд, баруун уушигны үндэс болон өсөх гол судасны хажууд байрладаг анатомийн байрлалыг дурдах. 2. Хавдар зэрэг массаар шахгдахад хана нь зөөлөн, даралтанд амархан автдаг венийн цусан хангамж саатаж, дээд биеэс (толгой, хүзүү, цээж) ирэх цусны урсгал хоригдож хаван үүсдэг болохыг тайлбарлах.', 'superior vena cava', 2);
  end if;
end;
$$;

do $$
declare e_id bigint;
begin
