      values ('Венийн судас: арьсан доорх их вен', 'Veins: great saphenous vein', 'Венийн судас', 'basic', 6, 80, 'published', 'venous', 'great saphenous vein', 'арьсан доорх их вен', 'ai')
      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Great saphenous vein (арьсан доорх их вен) нь доод мөчний аль хэсгээр дээш өгсөж, хаана цутгадаг вэ?', 'Which anatomical pathway does the great saphenous vein follow in the lower limb before draining into its terminal vein?', '["Доод мөчний гадна талар өгсөж, суганы венд цутгана", "Доод мөчний урд дотор талар өгсөж, гуяны венд (femoral vein) цутгана", "Доод мөчний ар талар өгсөж, өвдөгний хонхорхойн венд цутгана", "Доод мөчний гүн судлуудын хамт өгсөж, доიд хөндий венд шууд цутгана"]', 1, 'Great saphenous vein нь арьсан доорх өнгэц вен бөгөөд доод мөчний дотор тал болон гуяны урд дотор хэсгээр өгсөж, цавины орчимд гуяны венд (femoral vein) цутгадаг болохыг мэддэг байх.', 'great saphenous vein', 2),
      (e_id, 2, 'mcq', 'Great saphenous vein (арьсан доорх их вен)-тэй хамт явах мэдрэлийг нэрлэнэ үү.', 'Which nerve travels in close anatomical relationship with the great saphenous vein in the leg?', '["Nervus saphenus", "Nervus suralis", "Nervus fibularis communis", "Nervus tibialis"]', 0, 'Great saphenous vein нь шилбэний хэсэгт n. saphenus (сафенус мэдрэл)-тэй хамт яг зэрэгцэн байрладаг анатомийн онцлогтой.', 'great saphenous vein', 2),
      (e_id, 3, 'mcq', 'Great saphenous vein (арьсан доорх их вен) нь доод мөчний анатомийн хувьд ямар судлалын системд хамаарагддаг вэ?', 'To which venous system of the lower extremity does the great saphenous vein belong anatomically?', '["Артерийн систем", "Лимфийн судасны систем", "Өнгөц венүүдийн систем", "Гүн венүүдийн систем"]', 2, 'Great saphenous vein нь доод мөчний арьсан доор байрладаг өнгөц венийн системд (superficial venous system) хамаардаг.', 'great saphenous vein', 2),
      (e_id, 4, 'mcq', 'Great saphenous vein (арьсан доорх их вен)-ний дотор гадаргуу дээр цусыг зөвхөн нэг чиглэлд урсгах ямар бүтцийн элемент олон тоотой байдаг вэ?', 'What structural elements are numerous along the lumen of the great saphenous vein to ensure unidirectional blood flow?', '["Лимфийн зангилаанууд", "Гөлгөр булчингийн цагиргууд", "Хавхлагууд (valves)", "Мэдрэлийн төгсгөлүүд"]', 2, 'Венийн цусны буцаж урсах урсгалыг сааруулах зорилгоор great saphenous vein дотор олон тооны хавхлагууд (valves) байрладаг.', 'great saphenous vein', 2),
      (e_id, 5, 'case', 'Өвчтөн 45 настай эрэгтэй, баруун шилбэний дотор тал болон гуяар судлууд нь зангиралдан томорч мушгирсан, хүнд оргиж өвдөх шинж тэмдэгтэй ирэв. Эмч үзлэгээр доод мөчний өнгөц венийн системийн үйл ажиллагааны алдагдал буюу варикоз гэж оношложээ. Энэ эмгэгийн үед өргөжиж гэмтдэг, хүний биеийн хамгийн урт өнгөц венийн бүтцийг анатомийн хувьд тодорхойлж, түүний эхлэх цэг болон төгсгөл (цутгах газар)-ийг бичнэ үү.', 'A 45-year-old male presents with tortuous, dilated veins along the medial aspect of the right leg and thigh, accompanied by a heavy sensation. The physician diagnoses superficial venous insufficiency. Anatomically describe the longest superficial vein of the body affected in this condition, including its exact origin and termination point.', '[]', null, 'Оюутан дараах зүйлсийг бүтэн бичсэн байна: 1. Great saphenous vein (арьсан доорх их вен) нь хүний биеийн хамгийн урт өнгөц вен болохыг дурдах. 2. Эхлэх цэг: Хөлийн дотор талын венийн нум (dorsal venous arch-ийн дотор хэсэг)-ээс эхэлдэг. 3. Явах зам: Шагайны дотор талын ар өгсөж, шилбэний дотор талаар n. saphenus-тай хамт явж, өвдөгний үений ар талаар биш урд дотор талаар өгсөж гуяанд хүрнэ. 4. Төгсгөл: Цавины ховил орчимд фасцийн нүхээр (hiatus saphenus) нэвтэрч гуяны венд (femoral vein) цутгадаг болохыг бүтэн зөв тайлбарласан байх.', 'great saphenous vein', 2);
  end if;
end;
$$;

do $$
