      returning id into e_id;
    insert into public.exam_questions (exam_id, position, kind, prompt, prompt_en, options, answer, rubric, concept, points) values
      (e_id, 1, 'mcq', 'Хаалганы вен (portal vein) нь ямар хоёр судлуудын нийлж үүсдэг вэ?', 'The portal vein is formed by the union of which two veins?', '["Дээд болон доод цайвар гэдэсний венийн судлууд (Superior and inferior mesenteric veins)", "Элэгний вен болон дэлүүний вен (Hepatic veins and splenic vein)", "Бөөрний вен болон доод хөндий вен (Renal vein and inferior vena cava)", "Дээд цайвар гэдэсний вен болон дэлүүний вен (Superior mesenteric vein and splenic vein)"]', 3, 'Зөв хариулт: Дээд цайвар гэдэсний вен болон дэлүүний вен нийлж хаалганы венийг үүсгэдэг.', 'portal vein', 2),
      (e_id, 2, 'mcq', 'Хаалганы венийн систем (portal system) нь голчлон аль эрхтнүүдээс цусыг цуглуулж элэг рүү хүргэдэг вэ?', 'The portal venous system primarily collects blood from which organs and delivers it to the liver?', '["Доод мөчдийн булчингууд", "Цээжний хөндийн эрхтнүүд", "Хэвлийн хөндийн сондгой эрхтнүүд буюу ходоод, гэдэс, дэлүү, нойр булчирхай", "Бага аарцгийн эрхтнүүд"]', 2, 'Зөв хариулт: Хэвлийн хөндийн хоол боловсруулах эрхтэн тогтолцоо болон дэлүү, нойр булчирхайн цусыг цуглуулдаг.', 'portal vein', 2),
      (e_id, 3, 'mcq', 'Хаалганы вен (portal vein) элэгний хаалгаар (porta hepatis) орохдоо ямар судлуудтай зэрэгцэн байрладаг вэ?', 'As the portal vein enters the porta hepatis, with which other structures does it run alongside?', '["Доод хөндий вен болон гол судас (Inferior vena cava and aorta)", "Дэлүүний артери ба вен (Splenic artery and vein)", "Элэгний артери болон цөсний ерөнхий цорго (Proper hepatic artery and common bile duct)", "Элэгний венийн судлууд болон тунгалагийн судлууд (Hepatic veins and lymphatics)"]', 2, 'Зөв хариулт: Элэгний артери болон цөсний ерөнхий цорготой хамт элэгний жижиг гурвалсан бүтцийг бүрдүүлж байрлана.', 'portal vein', 2),
      (e_id, 4, 'mcq', 'Хаалганы венийн даралт хэт ихсэх эмгэг байдлыг юу гэж нэрлэдэг вэ?', 'What is the medical term for elevated blood pressure within the portal venous system?', '["Системийн гипертензи (Systemic hypertension)", "Уушигны гипертензи (Pulmonary hypertension)", "Хаалганы венийн даралт ихсэх өвчин буюу портал гипертензи (Portal hypertension)", "Бөөрний судасны гипертензи (Renal vascular hypertension)"]', 2, 'Зөв хариулт: Портал гипертензи.', 'portal vein', 2),
      (e_id, 5, 'case', '45 эрэгтэй архины шалтгаант элэгний хатуурал оноштойгоор эмчлүүлж байна. Биеийн үзлэгээр хэвлийн хөндийд шингэн хуримтлагдсан (ascites) болон улаан хоолойн венийн өргөсөл илэрчээ. Энэхүү эмнэлзүйн байдал нь аль судасны цусны эргэлтийн сааталтай холбоотой вэ? Уг судасны үүсэх анатомийн байрлал болон функциональ онцлогийг тайлбарлана уу.', 'A 45-year-old male with alcoholic cirrhosis presents with ascites and esophageal varices. This clinical condition is related to impaired blood flow in which vessel? Describe its anatomical formation and functional significance.', '[]', null, 'Бүтэн хариултын шаардлага: 1. Өртсөн судас: Хаалганы вен (portal vein). 2. Анатомийн үүсэл: Дээд цайвар гэдэсний вен болон дэлүүний вен нойр булчирхайн толгойн ард нийлж үүсдэг. 3. Функциональ онцлог: Хоол боловсруулах замаас шимэгдсэн шим тэжээлтэй цусыг элэг рүү зөөвөрлөж шүүх үүрэгтэй бөгөөд элэгний хатуурал үед уг судсаар цус урсахад саад учирч портал гипертензи үүсгэнэ.', 'portal vein', 2);
  end if;
end;
$$;

